window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bcb32656680d446b"]={"versions": [{"id": "FIG-bcb32656680d446b", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm aus der AUTOSAR Classic Platform Spezifikation (<code>AUTOSAR_SWS_E2ELibrary</code>). Es illustriert das Entwurfsmuster eines senderseitigen Transmission Managers innerhalb einer ECU, bei dem mehrere ungeschützte Quell-Datenelemente aus verschiedenen Software-Components über eine vermittelnde Komponente zusammengeführt und anschließend E2E-geschützt an die RTE übergeben werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten auf ihren Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>SWC1</code>: Quell-Software-Component für Datenelement <code>data1</code>.\n</li><li><code>SWC2</code>: Quell-Software-Component für Datenelement <code>data2</code>.\n</li><li><code>RTE</code>: AUTOSAR Runtime Environment als Kommunikationsvermittler.\n</li><li><code>SWC3</code> mit Stereotyp <code>«transmissio...</code> (Transmission Manager): Aggregierende Software-Component.\n</li><li><code>E2E</code>: E2E-Schutzschicht bzw. E2E-Protection-Wrapper (<code>E2EPW</code>).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data1)</code>: Sender-API von SWC1 an die RTE.\n</li><li><code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data2)</code>: Sender-API von SWC2 an die RTE.\n</li><li><code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data1)</code>: Empfänger-API von SWC3 zum Auslesen aus der RTE.\n</li><li><code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data2)</code>: Empfänger-API von SWC3 zum Auslesen aus der RTE.\n</li><li>Interne Operation an SWC3: <code>Merge, selection and conversion data elements(data1, data2): da...</code> (Verarbeitung zu Ziel-Datenelement <code>data3</code>).\n</li><li><code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>: Aufruf des E2E-Protection-Wrappers durch SWC3 zur Berechnung und Hinzufügung der E2E-Header-/Prüfdaten (CRC, Counter).\n</li><li><code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>: Absenden der E2E-geschützten Daten durch den Protection-Wrapper an die RTE.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>SWC1</code> sendet über <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data1)</code> das Datenelement <code>data1</code> an die RTE.\n</li><li>Zeitversetzt sendet <code>SWC2</code> über <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data2)</code> das Datenelement <code>data2</code> an die RTE.\n</li><li><code>SWC3</code> (Transmission Manager) liest nacheinander über <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data1)</code> und <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data2)</code> beide Datenelemente von der RTE ab.\n</li><li><code>SWC3</code> führt intern eine Aggregation durch (<code>Merge, selection and conversion data elements(data1, data2): da...</code>), woraus das kombinierte Signal-/Datenelement <code>data3</code> resultiert.\n</li><li><code>SWC3</code> übergibt das kombinierte Datenelement mittels <code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;(data3)</code> an den E2E-Protection-Wrapper.\n</li><li>Der E2E-Protection-Wrapper sichert die Daten ab und ruft <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data3)</code> auf, um das geschützte Datenelement an die RTE zur weiteren Übertragung (COM/Bus) weiterzuleiten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als architektonische Richtlinie und Beispielsequenz zur Umsetzung von E2E-Schutz bei komplexer Datenaggregation. Da der AUTOSAR E2E-Standard die Absicherung auf PDU- bzw. Datenelement-Ebene vorsieht, dürfen Signale aus unterschiedlichen Software-Komponenten nicht einzeln partiell abgesichert werden, wenn sie in einer gemeinsamen E2E-geschützten Botschaft übertragen werden sollen. Die Verwendung eines dedizierten Transmission Managers (<code>SWC3</code>) entkoppelt die signalgebenden Komponenten (<code>SWC1</code>, <code>SWC2</code>) von der E2E-Berechnung und bündelt die Verantwortlichkeit für Datenkonvertierung, Zykluszeitabstimmung und E2E-Serialisierung vor dem COM-Versand.</p>"}, {"id": "FIG-dce22bc06fdd518f", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm aus der AUTOSAR Classic Platform Spezifikation (<code>AUTOSAR_SWS_E2ELibrary</code>). Es illustriert das Entwurfsmuster eines senderseitigen Transmission Managers innerhalb einer ECU, bei dem mehrere ungeschützte Quell-Datenelemente aus verschiedenen Software-Components über eine vermittelnde Komponente zusammengeführt und anschließend E2E-geschützt an die RTE übergeben werden.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten auf ihren Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>SWC1</code>: Quell-Software-Component für Datenelement <code>data1</code>.\n</li><li><code>SWC2</code>: Quell-Software-Component für Datenelement <code>data2</code>.\n</li><li><code>RTE</code>: AUTOSAR Runtime Environment als Kommunikationsvermittler.\n</li><li><code>SWC3</code> mit Stereotyp <code>«transmissio...</code> (Transmission Manager): Aggregierende Software-Component.\n</li><li><code>E2E</code>: E2E-Schutzschicht bzw. E2E-Protection-Wrapper (<code>E2EPW</code>).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data1)</code>: Sender-API von SWC1 an die RTE.\n</li><li><code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data2)</code>: Sender-API von SWC2 an die RTE.\n</li><li><code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data1)</code>: Empfänger-API von SWC3 zum Auslesen aus der RTE.\n</li><li><code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data2)</code>: Empfänger-API von SWC3 zum Auslesen aus der RTE.\n</li><li>Interne Operation an SWC3: <code>Merge, selection and conversion data elements(data1, data2): da...</code> (Verarbeitung zu Ziel-Datenelement <code>data3</code>).\n</li><li><code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>: Aufruf des E2E-Protection-Wrappers durch SWC3 zur Berechnung und Hinzufügung der E2E-Header-/Prüfdaten (CRC, Counter).\n</li><li><code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data3)</code>: Absenden der E2E-geschützten Daten durch den Protection-Wrapper an die RTE.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>SWC1</code> sendet über <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data1)</code> das Datenelement <code>data1</code> an die RTE.\n</li><li>Zeitversetzt sendet <code>SWC2</code> über <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data2)</code> das Datenelement <code>data2</code> an die RTE.\n</li><li><code>SWC3</code> (Transmission Manager) liest nacheinander über <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data1)</code> und <code>Rte_Read_&lt;p&gt;_&lt;o&gt;(data2)</code> beide Datenelemente von der RTE ab.\n</li><li><code>SWC3</code> führt intern eine Aggregation durch (<code>Merge, selection and conversion data elements(data1, data2): da...</code>), woraus das kombinierte Signal-/Datenelement <code>data3</code> resultiert.\n</li><li><code>SWC3</code> übergibt das kombinierte Datenelement mittels <code>E2EPW_Write_&lt;p&gt;_&lt;o&gt;(data3)</code> an den E2E-Protection-Wrapper.\n</li><li>Der E2E-Protection-Wrapper sichert die Daten ab und ruft <code>Rte_Write_&lt;p&gt;_&lt;o&gt;(data3)</code> auf, um das geschützte Datenelement an die RTE zur weiteren Übertragung (COM/Bus) weiterzuleiten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als architektonische Richtlinie und Beispielsequenz zur Umsetzung von E2E-Schutz bei komplexer Datenaggregation. Da der AUTOSAR E2E-Standard die Absicherung auf PDU- bzw. Datenelement-Ebene vorsieht, dürfen Signale aus unterschiedlichen Software-Komponenten nicht einzeln partiell abgesichert werden, wenn sie in einer gemeinsamen E2E-geschützten Botschaft übertragen werden sollen. Die Verwendung eines dedizierten Transmission Managers (<code>SWC3</code>) entkoppelt die signalgebenden Komponenten (<code>SWC1</code>, <code>SWC2</code>) von der E2E-Berechnung und bündelt die Verantwortlichkeit für Datenkonvertierung, Zykluszeitabstimmung und E2E-Serialisierung vor dem COM-Versand.</p>"}], "trans": [{"from": "FIG-bcb32656680d446b", "to": "FIG-dce22bc06fdd518f", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
